<?php require_once 'layout.php'; require_user(); $uid=current_user()['id']; $rs=db()->query("SELECT * FROM orders WHERE user_id=$uid ORDER BY id DESC"); page_header('My Orders'); ?><h1>My Orders</h1><div class="cart-box"><table><tr><th>Token</th><th>Total</th><th>Status</th><th>Orders Ahead</th><th>Estimated Time</th><th>Date</th></tr><?php while($o=$rs->fetch_assoc()):?><tr><td>#<?=$o['token_number']?></td><td>₹<?=number_format($o['total_amount'],0)?></td><td><span class="badge <?=strtolower($o['status'])?>"><?=$o['status']?></span></td><td><?=orders_ahead($o)?></td><td><?=wait_minutes($o['status'])?> minutes</td><td><?=date('d M Y h:i A',strtotime($o['created_at']))?></td></tr><?php endwhile;?></table></div><?php page_footer(); ?>
